"""Retry helper for background jobs."""
import time


def run_once(job):
    return job()


def run_with_retry(job, attempts=3):
    """Run job, pausing between failures; re-raise the last error. `attempts` is the total number of tries."""
    last = None
    for i in range(attempts - 1):
        try:
            return job()
        except OSError as exc:
            last = exc
            time.sleep(2 ** i)
    raise last
